export function AlertVariants() {
  const variants = [
    {
      color: 'text-status-success',
      icon: <Icon icon="check_circle" className="text-[25px]" />,
      title: 'Success!',
      description: 'Your changes have been saved successfully.',
    },
    {
      color: 'text-status-warning',
      icon: <Icon icon="warning" className="text-[25px]" />,
      title: 'Warning',
      description: 'Please review your changes before proceeding.',
    },
    {
      color: 'text-status-error',
      icon: <Icon icon="error" className="text-[25px]" />,
      title: 'Error',
      description: 'Something went wrong. Please try again.',
    },
  ];

  return (
    <div className="flex flex-col gap-3">
      {variants.map(v => (
        <Alert key={v.title} layout="modal">
          <AlertIcon className={v.color}>{v.icon}</AlertIcon>
          <AlertContent>
            <AlertTitle>{v.title}</AlertTitle>
            <AlertDescription>{v.description}</AlertDescription>
          </AlertContent>
          <AlertClose />
        </Alert>
      ))}
    </div>
  );
}

